package com.dy.artisan3d.data.repositoryimport com.dy.artisan3d.data.mapper.toDomainimport com.dy.artisan3d.data.model.artisan.about.ArtisanAboutResponseimport com.dy.artisan3d.domain.model.artisan.ArtisanAboutimport com.dy.artisan3d.domain.repository.ArtisanAboutRepositoryimport com.dy.artisan3d.util.Constants.BASE_URLimport com.dy.artisan3d.util.safeApiCallimport io.ktor.client.HttpClientimport io.ktor.client.call.bodyimport io.ktor.client.request.getclass ArtisanAboutRepositoryImpl(    private val httpClient: HttpClient,) : ArtisanAboutRepository {    override suspend fun getAboutData(lang: String): Result<List<ArtisanAbout>> {        val response: Result<ArtisanAboutResponse> = safeApiCall {            httpClient.get(BASE_URL + "abouts").body()        }        return response.map { response ->            response.data?.map { it.toDomain(lang) } ?: emptyList()        }    }}